<?php use App\Core\Helpers as H; ?>
<header class="message-heading"><div><h1><?=ucfirst(H::e($side))?> messages</h1><p class="muted"><?=$totalUnread?> unread message<?=$totalUnread===1?'':'s'?></p></div><a class="btn secondary" href="/<?=$side?>/messages<?=$archived?'':'?archived=1'?>"><?=$archived?'Active':'Archived'?></a></header>
<?php if(!$conversations):?><section class="card empty-state"><h2>No <?=$archived?'archived':'active'?> conversations</h2><p><?=$archived?'Archived conversations will remain available here.':'Start a private conversation from a product, storefront, or eligible order.'?></p></section><?php endif;?>
<div class="message-inbox"><?php foreach($conversations as $c):?><a class="message-row <?=((int)$c['unread_count']>0)?'unread':''?>" href="/<?=$side?>/messages/<?=$c['id']?>"><div><strong><?=$side==='buyer'?H::e($c['shop_name']):H::e($c['buyer_name'])?></strong><?php if($c['context_label']):?><span><?=H::e($c['context_label'])?></span><?php endif;?><?php if($c['order_id']):?><span>Order #<?=$c['order_id']?></span><?php endif;?></div><p><?=H::e(mb_substr((string)($c['latest_body']!==null&&$c['latest_body']!==''?$c['latest_body']:((int)$c['latest_attachment_count']>0?'Image attachment':'No messages yet')),0,100))?></p><?php if($c['unread_count']):?><span class="badge"><?=$c['unread_count']?> unread</span><?php endif;?></a><?php endforeach;?></div>
